import{mix}from './world.js';
import{memoryBias,motives}from './behavior.js';
import{recordExperience}from './life-state.js';
import{diverseRoutine,meaningAllowed,learnedResponse,familiarSituation,learnResponse,semanticKey,validSemanticMeta}from './event-semantics.js';
const clamp=n=>Math.max(0,Math.min(100,n));
const carer=s=>s.humans?.find(h=>h.id===s.caregiverId&&h.area===s.areaId);
const sibling=s=>s.relations?.find(r=>r.kind==='sibling'&&r.active&&r.area===s.areaId);
const changed=(s,kind)=>s.worldModel.profile?.changes.some(c=>c.area===s.areaId&&c.kind===kind&&s.day-c.day<=30);
const action=(id,text,goal,result,delta,followup,condition=null)=>({id,text,goal,result,delta,followup,condition});
// Each cause has distinct constraints, actions, tradeoffs and consequential followup.
export const SITUATIONS=[
{id:'litter-boundary',min:26,max:83,goal:'play',conflict:'play-pressure',role:'sibling',actor:sibling,ok:s=>!!sibling(s)&&s.worldModel.origin.mother,text:(s,a)=>`${a.name}가 내 등에 앞발을 얹고 계속 몸을 굴린다. 잠자리 한쪽에는 어미의 몸과 비어 있는 천 자리가 있다. 내 몸을 움직일 만큼의 공간은 아직 좁다.`,actions:[action('soft-play','앞발을 낮추고 짧게 몸을 굴려 논다','play','잠깐 밀고 밀린 뒤 먼저 몸을 멈췄다. 상대도 움직임을 줄인다.',{comfort:3,fatigue:3},'짧게 놀고 멈추는 몸짓이 조금 익숙해졌다.'),action('turn-away','몸을 돌려 빈 천 자리에서 쉰다','rest','몸을 돌려 떨어지자 형제가 다른 쪽으로 움직였다. 쉬고 싶을 때 떨어질 공간이 남았다.',{stress:-3,fatigue:-3},'놀이가 길어지면 비어 있는 자리로 몸을 옮겨 쉰다.')]},
{id:'changed-home-route',min:90,goal:'explore',conflict:'unfamiliar-layout',role:'caregiver',actor:carer,ok:s=>s.home==='family'&&s.lastAreaChange&&s.day-s.lastAreaChange.day<21,text:(s,a)=>`다른 집에 온 뒤 물그릇이 놓인 방까지의 길이 아직 낯설다. ${a.name}는 복도 끝에 앉아 있고, 미끄럽지 않은 담요가 두 방 사이에 놓였다.`,actions:[action('follow-mat','담요가 이어진 길을 천천히 밟아 본다','explore','담요를 따라 방을 오갔다. 물그릇에서 몇 모금 마시고 같은 길로 돌아왔다.',{thirst:-8,comfort:2},'담요가 놓인 길을 따라 물과 잠자리 사이를 오가기 시작했다.'),action('call-near','익숙한 사람 곁에서 작은 소리를 낸다','social','사람 쪽으로 몸을 돌리고 잠시 기다렸다.',{familyBond:2,stress:-1},'낯선 방에서 멈출 때 가까운 사람의 움직임을 다시 살핀다.') ]},
{id:'care-time-shortage',min:120,goal:'social',conflict:'limited-attention',role:'caregiver',actor:carer,ok:s=>s.home==='family'&&carer(s)?.time<40&&changed(s,'work-schedule'),text:()=> '문이 열린 뒤 익숙한 사람이 돌아왔지만 곧 물건을 정리하러 움직인다. 바닥에는 내 천 장난감이 있고, 쉬던 담요 자리도 비어 있다.',actions:[action('bring-toy','천 장난감을 물고 가까운 빈 바닥에 내려놓는다','social','장난감을 사람 가까운 바닥에 내려놓고 몸을 낮췄다.',{familyBond:2,fatigue:2},'놀이를 청할 때 장난감을 같은 빈자리에 가져다 놓는다.'),action('solo-toy','장난감을 내 자리로 가져가 앞발로 붙잡는다','play','내 자리에서 장난감을 물고 당겼다. 사람이 오가지 않는 쪽에서 짧게 놀았다.',{comfort:3,fatigue:3},'사람이 바쁠 때 내 자리에서 물건을 갖고 노는 시간이 생겼다.'),action('settle','담요를 모아 몸을 눕히고 쉰다','rest','담요를 몸 가까이 모았다. 오가는 발을 피한 자리에서 먼저 쉬었다.',{fatigue:-5,stress:-2},'사람의 일이 길어지는 날에는 조용한 담요 자리를 먼저 쓴다.')]},
{id:'crowded-rest',min:90,goal:'rest',conflict:'shared-space',role:'caregiver',actor:carer,ok:s=>s.home==='shelter'&&s.environmentModel?.facility==='shelter'&&s.worldModel.profile.society.crowding>65&&s.needs.fatigue>25,text:()=> '복도 여러 칸에서 움직이는 소리가 겹친다. 직원은 칸 앞의 물을 갈고 있고, 칸 안쪽에는 시야가 덜 트인 마른 잠자리가 있다.',actions:[action('inside-bed','칸 안쪽의 가려진 잠자리로 들어가 눕는다','rest','통로가 덜 보이는 쪽으로 몸을 옮겼다. 오가는 움직임에서 떨어져 쉰다.',{stress:-4,fatigue:-4},'복도가 붐비면 안쪽 잠자리로 먼저 몸을 옮긴다.'),action('staff-side','직원이 있는 쪽에 앉아 몸을 낮춘다','social','칸 안에서 직원 쪽에 몸을 낮추고 기다렸다.',{trust:2,stress:-1},'물그릇을 갈 때면 익숙한 직원의 움직임을 구별한다.')]},
{id:'missing-water',min:100,goal:'water',conflict:'resource-loss',role:'environment',actor:s=>({id:'water-place:'+s.areaId}),ok:s=>s.home==='street'&&s.needs.thirst>35&&changed(s,'water-access')&&s.worldModel.profile.geography.water<55,text:s=>`전에 물을 마시던 벽 아래 그릇이 없다. 같은 쪽 골목에는 그늘과 처마가 이어져 있지만, 큰길에는 ${s.world==='heat'?'강한 햇빛이 내려쬔다':s.world==='rain'?'빗물이 흐르고 차가 오간다':'차가 오간다'}.`,actions:[action('shaded-search','차도를 건너지 않고 그늘진 골목을 짧게 살핀다','water','처마가 이어진 쪽을 짧게 돌며 물 있는 자리를 살폈다.',{fatigue:3},'다음에도 큰길을 건너지 않는 쪽부터 물 있는 자리를 확인한다.'),action('save-energy','처마 아래에서 몸을 눕히고 움직임을 줄인다','rest','마른 그늘에 몸을 낮췄다. 당장 물을 마시지는 못했지만 먼 길로 나가지 않고 쉰다.',{fatigue:-5,thirst:2},'물이 없는 날에는 먼 길을 돌기 전에 그늘에서 쉬는 시간이 늘었다.')]},
{id:'wet-sleeping-place',min:90,goal:'rest',conflict:'wet-bedding',role:'environment',actor:s=>({id:'sleeping-place:'+s.areaId}),ok:s=>s.home==='street'&&s.world==='rain'&&s.needs.fatigue>25,text:()=> '처마 끝에서 떨어진 물이 누워 있던 천 가장자리까지 스며든다. 벽 안쪽의 마른 바닥과 조금 높은 상자 옆에 몸을 둘 틈이 남아 있다.',actions:[action('dry-floor','젖지 않은 벽 안쪽 바닥으로 자리를 옮긴다','rest','천에서 일어나 마른 바닥으로 몸을 옮겼다. 비가 닿지 않는 쪽에서 다시 웅크렸다.',{comfort:3,fatigue:-3},'비가 오면 천이 젖기 전에 벽 안쪽 마른 자리를 살핀다.'),action('move-cloth','마른 천 끝을 물고 벽 쪽으로 조금 당긴다','explore','물에 닿지 않은 천 끝을 당겨 몸 아래에 모았다.',{comfort:2,fatigue:2},'천을 몸 아래에 모아 눕는 움직임이 익숙해졌다.',s=>s.day>=120&&s.clinical.mobility>=80)]}
];
export function initSituations(s){return s.situations??={version:1,next:s.day+26,seen:{},followups:[]};}
function actorExists(s,d,id){if(d.role==='environment')return id===d.actor(s).id;if(d.role==='sibling')return !!s.relations.find(a=>a.id===id&&a.active&&a.area===s.areaId);return s.caregiverId===id&&!!s.humans.find(h=>h.id===id&&h.area===s.areaId);}
export function situationOptions(s,d){return d.actions.filter(o=>(!o.condition||o.condition(s))&&(!['explore','play','water'].includes(o.goal)||(s.day>=s.milestones.walking&&s.clinical.mobility>=55)));}
export function situationEligible(s,d){return s.alive&&s.day>=d.min&&s.day<=(d.max??Infinity)&&s.day>=s.milestones.walking&&!s.story.lost&&!s.medical.episode&&!s.clinical.active&&d.ok(s)&&!!d.actor(s)&&situationOptions(s,d).length>=2;}
export function composeSituation(s,d){if(!situationEligible(s,d))return null;const actor=d.actor(s),options=situationOptions(s,d);const semantic={version:1,coverage:'explicit',cause:d.id,goal:d.goal,conflict:d.conflict,role:d.role,actor:actor.id,area:s.areaId,actions:options.map(o=>o.id),actionTypes:options.map(o=>o.goal)};return {id:'composed:'+d.id,text:d.text(s,actor),options,context:{actor:actor.id,area:s.areaId,place:s.worldModel.context.label,semantic,cause:d.id,weather:s.world,worldSequence:s.worldModel.profile.sequence,need:{hunger:s.needs.hunger,thirst:s.needs.thirst,fatigue:s.needs.fatigue},risk:{traffic:s.worldModel.profile.geography.traffic,water:s.worldModel.profile.geography.water},memories:s.episodes.filter(m=>m.target===actor.id).slice(-3).map(m=>m.id),constraints:{species:'dog',min:d.min,max:d.max??null,walking:s.milestones.walking},provenance:'authored-game-assumption'}};}
export function validSituation(id){return SITUATIONS.some(d=>'composed:'+d.id===id);}
export function routineAction(s,p){const known=learnedResponse(s,p.context.semantic);if(known)return known;if(!familiarSituation(s,p.context.semantic))return null;const m=motives(s),weights=p.options.map(o=>1+(m[o.goal]??40)/35+(o.goal==='social'?memoryBias(s,p.context.actor)/15:0));let roll=mix(`${s.seed}:${s.day}:${p.id}`,1805)/4294967296*weights.reduce((a,b)=>a+b,0);for(let i=0;i<p.options.length;i++){roll-=Math.max(.1,weights[i]);if(roll<=0)return p.options[i].id;}return p.options.at(-1).id;}
export function canResolveSituation(s,p,id){const d=SITUATIONS.find(d=>'composed:'+d.id===p.id);return !!d&&p.context?.area===s.areaId&&p.context.actor===d.actor(s)?.id&&actorExists(s,d,p.context.actor)&&situationEligible(s,d)&&situationOptions(s,d).some(o=>o.id===id)&&p.options.some(o=>o.id===id);}
export function resolveSituation(s,p,id,{log,remember},automatic=false){if(!p.id.startsWith('composed:')||!canResolveSituation(s,p,id))return false;const d=SITUATIONS.find(d=>'composed:'+d.id===p.id),o=d.actions.find(o=>o.id===id),h=carer(s),target=p.context.actor;
const before=automatic?{logLength:s.log.length,...Object.fromEntries(['health','comfort','trust','stress','familyBond','dogBond'].map(k=>[k,s[k]])),...s.needs}:null;
const responsive=d.role==='caregiver'&&mix(`${s.seed}:${s.day}:${target}`,1801)%100<(h.time+h.knowledge)/2+memoryBias(s,target);
let text=o.result,delta={...o.delta};
if(['bring-toy','call-near','staff-side'].includes(id)){if(responsive){text+=' 사람이 가까이 앉아 짧게 손을 내민다. 내 반응을 보고 움직임을 멈춘다.';delta.familyBond=(delta.familyBond||0)+2;}else{text+=' 사람은 하던 일을 이어 간다. 더 따라가지 않고 내 자리에 머문다.';delta.stress=(delta.stress||0)+2;}}
if(id==='shaded-search'){const found=mix(`${s.seed}:${s.day}:${s.areaId}`,1802)%100<s.worldModel.profile.geography.water;if(found){text+=' 빈 벽 옆의 얕은 물을 조금 마시고 돌아왔다.';delta.thirst=-9;}else{text+=' 오늘은 마실 물을 찾지 못해 그늘로 돌아왔다.';delta.thirst=2;}}
for(const [k,v]of Object.entries(delta)){const owner=k in s.needs?s.needs:s;owner[k]=clamp(owner[k]+v);}
if(o.goal==='explore')s.worldModel.traits.independence=clamp(s.worldModel.traits.independence+.5);
log(s,automatic?'composed-routine':'composed-result',text);const storyId='causal:'+p.uid;
Object.assign(s.log.at(-1),{actorId:target,placeLabel:p.context.place,semantic:p.context.semantic,cause:d.id,purpose:o.goal,storyId,automatic,resultPattern:responsive?'supported':'independent'});
learnResponse(s,p.context.semantic,id,(delta.stress??0)<=0&&!(d.goal==='water'&&(delta.thirst??0)>=0));
const state=initSituations(s);state.followups.push({id:storyId,start:s.day,due:s.day+4,area:s.areaId,actor:target,kind:d.id,text:o.followup,action:id,goal:o.goal,status:'waiting'});if(state.followups.length>64)state.followups=state.followups.slice(-64);remember(s,'cause:'+d.id+':'+id);if(automatic){const presentation=s.presentation;recordExperience(s,p,id,before);s.presentation=presentation;}return true;}
export function situationStep(s,{log,decision,remember}){const t=initSituations(s);for(const f of t.followups){if(f.status!=='waiting'||s.day<f.due)continue;const d=SITUATIONS.find(d=>d.id===f.kind);if(s.areaId!==f.area||s.story.lost||!actorExists(s,d,f.actor)){f.status='closed';continue;}if(s.medical.episode||s.clinical.active)continue;f.status='complete';s.comfort=clamp(s.comfort+1);log(s,'composed-followup',f.text);Object.assign(s.log.at(-1),{storyId:f.id,actorId:f.actor,cause:f.kind,purpose:f.goal,placeLabel:s.worldModel.context.label});return true;}
if(s.pending||s.day<t.next||s.medical.episode||s.clinical.active)return false;
const pool=SITUATIONS.map(d=>composeSituation(s,d)).filter(p=>p&&s.day-(t.seen[p.context.cause]??-1000)>=90&&(familiarSituation(s,p.context.semantic)||meaningAllowed(s,p.context.semantic)));
if(!pool.length){t.next=s.day+4;return false;}const p=diverseRoutine(s,pool,p=>p.context.semantic,1803),known=routineAction(s,p);p.uid=`learned:${s.lifeId}:${p.id}:${s.day}`;
if(known){resolveSituation(s,p,known,{log,remember},true);}else if(!decision(s,p.id,p.text,p.options.map(o=>[o.id,o.text]),p.context))return false;
t.seen[p.context.cause]=s.day;t.next=s.day+20+mix(s.seed+s.day,1804)%21;return true;}
export function validateSituations(s){const t=s.situations;if(!t){if(s.pending?.id.startsWith('composed:'))throw Error('상황 원인이 없는 선택');return;}
if(t.version!==1||!Number.isInteger(t.next)||t.next<0||!t.seen||typeof t.seen!=='object'||!Object.values(t.seen).every(x=>Number.isInteger(x)&&x>=0&&x<=s.day)||!Array.isArray(t.followups)||t.followups.length>64||!t.followups.every(f=>typeof f.id==='string'&&typeof f.actor==='string'&&typeof f.area==='string'&&typeof f.text==='string'&&Number.isInteger(f.start)&&f.start>=0&&f.start<=s.day&&Number.isInteger(f.due)&&f.due>f.start&&SITUATIONS.some(d=>d.id===f.kind&&d.actions.some(o=>o.id===f.action))&&['waiting','complete','closed'].includes(f.status)))throw Error('손상된 인과 상황');
if(s.pending?.id.startsWith('composed:')&&(!validSemanticMeta(s.pending.context?.semantic)||s.pending.options.length<2||!s.pending.options.every(o=>canResolveSituation(s,s.pending,o.id))||semanticKey(s.pending.context.semantic)!==semanticKey(composeSituation(s,SITUATIONS.find(d=>'composed:'+d.id===s.pending.id))?.context.semantic||{})))throw Error('원인·개체와 맞지 않는 선택');}
